function site_info(string $key): string {
    static $information;
    $information ??= require __DIR__ . '/../config/site.php';
    return (string)($information[$key] ?? '');
}

function owner_email_link(): string {
    if (trim(site_info('contact_email')) === '') {
        return '<span>Контактну адресу не опубліковано. Це демонстраційний проєкт.</span>';
    }
    return '<a href="mailto:'.e(site_info('contact_email')).'">'.e(site_info('contact_email')).'</a>';
}

